/**
 * Calculate rental price breakdown
 */
export interface RentalPricing {
  days: number;
  dailyRate: number;
  subtotal: number;
  coverageRate: number;
  coverageFee: number;
  total: number;
  totalPrice: number;
}

export function calculateRentalPrice(
  dailyRate: number,
  startDate: Date,
  endDate: Date,
  category?: CategoryId
): RentalPricing {
  const days = calculateRentalDays(startDate, endDate);
  const dailyRateInCents = Math.round(dailyRate * 100);
  const subtotalInCents = dailyRateInCents * days;
  const subtotal = subtotalInCents / 100;

  const coverageRate = category ? COVERAGE_RATES[category] ?? 0 : 0;
  const coveragePercent = Math.round(coverageRate * 100);
  const coverageFeeInCents = Math.round((subtotalInCents * coveragePercent) / 100);
  const coverageFee = coverageFeeInCents / 100;

  const totalInCents = subtotalInCents + coverageFeeInCents;
  const total = totalInCents / 100;

  return {
    days,
    dailyRate,
    subtotal,
    coverageRate,
    coverageFee,
    total,
    totalPrice: total,
  };
}

/**
 * Format price in Mexican Pesos
 */
export function formatPrice(amount: number): string {
  return new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(amount);
}

